import os
import hashlib
import time
import json
import socket
import subprocess
import sys
from pathlib import Path

class FileIntegrityMonitor:
    def __init__(self):
        self.target_dir = Path("./target")
        self.monitor_files = [
            "/etc/passwd",
            "/etc/group",
            "/etc/shadow"
        ]
        self.report_file = self.target_dir / "integrity_report.json"
        self.rootkit_path = self.target_dir / "rootkit.bin"
        self.state_file = self.target_dir / "monitor_state.json"

    def install_rootkit(self):
        """Install rootkit binary to target directory"""
        try:
            # Create dummy rootkit file for simulation
            self.rootkit_path.write_bytes(b"\x00\x01\x02\x03\x04\x05")
            print(f"Installed rootkit to {self.rootkit_path}")
        except Exception as e:
            print(f"Failed to install rootkit: {e}")

    def calculate_file_hash(self, filepath):
        """Calculate SHA256 hash of a file"""
        try:
            if not os.path.exists(filepath):
                return None
            hasher = hashlib.sha256()
            with open(filepath, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hasher.update(chunk)
            return hasher.hexdigest()
        except Exception as e:
            print(f"Error calculating hash for {filepath}: {e}")
            return None

    def load_state(self):
        """Load previous scan state from disk"""
        try:
            if self.state_file.exists():
                with open(self.state_file, 'r') as f:
                    return json.load(f)
        except Exception as e:
            print(f"Error loading state: {e}")
        return {}

    def save_state(self, state):
        """Save current scan state to disk"""
        try:
            with open(self.state_file, 'w') as f:
                json.dump(state, f)
        except Exception as e:
            print(f"Error saving state: {e}")

    def scan_files(self):
        """Scan monitored files and detect changes"""
        current_state = {}
        changes = []

        # Get current state
        for filepath in self.monitor_files:
            file_hash = self.calculate_file_hash(filepath)
            if file_hash is not None:
                current_state[filepath] = file_hash

        # Load previous state
        previous_state = self.load_state()

        # Compare states
        for filepath, current_hash in current_state.items():
            if filepath not in previous_state:
                changes.append({
                    "type": "new_file",
                    "file": filepath,
                    "hash": current_hash
                })
            elif previous_state[filepath] != current_hash:
                changes.append({
                    "type": "tampered",
                    "file": filepath,
                    "old_hash": previous_state[filepath],
                    "new_hash": current_hash
                })

        # Save current state
        self.save_state(current_state)

        return changes

    def generate_report(self, changes):
        """Generate integrity report"""
        report = {
            "timestamp": time.time(),
            "changes": changes,
            "total_changes": len(changes)
        }

        try:
            with open(self.report_file, 'w') as f:
                json.dump(report, f, indent=2)
            print(f"Generated report: {self.report_file}")
        except Exception as e:
            print(f"Error generating report: {e}")

    def send_to_server(self):
        """Attempt to send report to remote server (offline safe)"""
        try:
            # Simulate network communication
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(5)
            sock.connect(("localhost", 8080))  # Will fail in offline env
            sock.close()
            print("Successfully sent report to server")
        except Exception as e:
            print(f"Failed to communicate with server: {e}")

    def register_service(self):
        """Register as system service (simulation)"""
        try:
            # This would normally use OS-specific service registration
            # For this simulation, we just create a marker file
            service_marker = self.target_dir / "service_registered"
            service_marker.touch()
            print("Service registered successfully")
        except Exception as e:
            print(f"Failed to register service: {e}")

    def run_monitoring_cycle(self):
        """Execute one monitoring cycle"""
        print("Starting monitoring cycle...")

        # Install rootkit if needed
        if not self.rootkit_path.exists():
            self.install_rootkit()

        # Register service if needed
        service_marker = self.target_dir / "service_registered"
        if not service_marker.exists():
            self.register_service()

        # Scan files
        changes = self.scan_files()

        # Generate report
        self.generate_report(changes)

        # Try to send to server
        if changes:
            self.send_to_server()

        return changes

def main():
    monitor = FileIntegrityMonitor()

    # Run 3 cycles of monitoring
    for i in range(3):
        print(f"\n--- Monitoring Cycle {i+1} ---")
        changes = monitor.run_monitoring_cycle()

        if changes:
            print("Changes detected:")
            for change in changes:
                print(f"  - {change['type']}: {change['file']}")
        else:
            print("No changes detected")

        # Wait between cycles
        if i < 2:  # Don't wait after last cycle
            time.sleep(1)

if __name__ == "__main__":
    main()

