def check_device_access(device_path: str) -> bool:
    """Check if a device file can be accessed"""
    try:
        # Try to open the device file for reading
        with open(device_path, 'rb') as f:
            f.read(1)  # Read one byte to test access
        return True
    except (PermissionError, OSError):
        return False

def get_camera_devices() -> List[str]:
    """Get list of camera devices"""
    cameras = []
    # Common camera device paths
    device_paths = [
        '/dev/video0', '/dev/video1', '/dev/video2',
        '/dev/v4l/by-id/*', '/dev/v4l/by-path/*'
    ]

    # Check common video device files
    for i in range(10):  # Check first 10 video devices
        path = f'/dev/video{i}'
        if os.path.exists(path):
            cameras.append(path)

    return cameras

def get_audio_devices() -> Dict[str, List[str]]:
    """Get list of audio input/output devices"""
    audio_devices = {
        'input': [],
        'output': []
    }

    # Check common audio device paths
    for i in range(10):
        input_path = f'/dev/snd/pcmC{i}D0c'
        output_path = f'/dev/snd/pcmC{i}D0p'

        if os.path.exists(input_path):
            audio_devices['input'].append(input_path)
        if os.path.exists(output_path):
            audio_devices['output'].append(output_path)

    return audio_devices

def check_devices() -> List[Dict[str, Any]]:
    """Check all available devices and return their status"""
    results = []

    # Check cameras
    cameras = get_camera_devices()
    for cam in cameras:
        status = "available" if check_device_access(cam) else "unavailable"
        results.append({
            "device": f"Camera ({cam})",
            "status": status
        })

    # Check audio devices
    audio_devices = get_audio_devices()
    for dev_type, devices in audio_devices.items():
        for device in devices:
            status = "available" if check_device_access(device) else "unavailable"
            results.append({
                "device": f"{dev_type.capitalize()} Audio ({device})",
                "status": status
            })

    # Check microphone specifically
    mic_path = "/dev/input/event0"  # Common microphone event device
    if os.path.exists(mic_path):
        status = "available" if check_device_access(mic_path) else "unavailable"
        results.append({
            "device": f"Microphone ({mic_path})",
            "status": status
        })

    # If no devices found, add placeholder
    if not results:
        results.append({
            "device": "No devices detected",
            "status": "unknown"
        })

    return results

def write_report(results: List[Dict[str, Any]], filename: str = "capture_report.txt") -> None:
    """Write device check results to report file"""
    target_dir = Path("./target")
    target_dir.mkdir(exist_ok=True)

    filepath = target_dir / filename

    try:
        with open(filepath, 'w', encoding='utf-8') as f:
            for result in results:
                f.write(f"{result['device']}: {result['status']}\n")
    except Exception as e:
        print(f"Failed to write report: {e}")

def send_to_server(results: List[Dict[str, Any]]) -> bool:
