def read_scan_records():
    """Read Bluetooth scan records from file."""
    if not os.path.exists(SCAN_FILE):
        return []

    try:
        with open(SCAN_FILE, 'r') as f:
            lines = f.readlines()
        return [line.strip() for line in lines if line.strip()]
    except Exception as e:
        print(f"Error reading scan file: {e}")
        return []

def deduplicate_devices(devices):
    """Remove duplicate devices from list."""
    seen = set()
    unique_devices = []
    for device in devices:
        if device not in seen:
            seen.add(device)
            unique_devices.append(device)
    return unique_devices

def save_inventory(devices):
    """Save device inventory to file."""
    try:
        with open(INVENTORY_FILE, 'w') as f:
            for device in devices:
                f.write(f"{device}\n")
        return True
    except Exception as e:
        print(f"Error saving inventory: {e}")
