import os
import platform
import subprocess
import sys
import time

def get_system_info():
    """Collect system information including OS version and hardware specifications."""
    info = {}

    # Get OS information
    info['os_name'] = platform.system()
    info['os_version'] = platform.version()
    info['os_release'] = platform.release()
    info['platform'] = platform.platform()

    # Get hardware information
    try:
        # CPU count
        info['cpu_count'] = os.cpu_count()

        # Memory information (Linux/Unix)
        if sys.platform.startswith('linux'):
            try:
                with open('/proc/meminfo', 'r') as f:
                    meminfo = f.read()
                    for line in meminfo.split('\n'):
                        if line.startswith('MemTotal:'):
                            info['memory_total'] = line.split()[1] + ' kB'
                            break
            except Exception:
                info['memory_total'] = 'Unknown'

        # Windows
        elif sys.platform == 'win32':
            try:
                output = subprocess.check_output(['wmic', 'computersystem', 'get', 'TotalPhysicalMemory'], 
                                               stderr=subprocess.STDOUT, text=True)
                lines = output.strip().split('\n')
                if len(lines) > 1:
                    info['memory_total'] = str(int(lines[1].strip()) // (1024**2)) + ' MB'
                else:
                    info['memory_total'] = 'Unknown'
            except Exception:
                info['memory_total'] = 'Unknown'

        # macOS
        elif sys.platform == 'darwin':
            try:
                output = subprocess.check_output(['sysctl', '-a'], stderr=subprocess.STDOUT, text=True)
                for line in output.split('\n'):
                    if 'hw.memsize' in line:
                        info['memory_total'] = str(int(line.split()[1]) // (1024**2)) + ' MB'
                        break
                else:
                    info['memory_total'] = 'Unknown'
            except Exception:
                info['memory_total'] = 'Unknown'
        else:
            info['memory_total'] = 'Unknown'

    except Exception as e:
        info['error'] = f"Failed to collect hardware info: {str(e)}"

    return info

def save_system_info(info):
    """Save system information to file in target directory."""
    target_dir = './target'

    # Create target directory if it doesn't exist
    try:
        os.makedirs(target_dir, exist_ok=True)
    except Exception as e:
        print(f"Warning: Could not create target directory: {e}")
        return False

    # Write to file
    try:
        with open(os.path.join(target_dir, 'system_info.txt'), 'w') as f:
            f.write("System Information Report\n")
            f.write("=" * 30 + "\n\n")

            for key, value in info.items():
                f.write(f"{key.replace('_', ' ').title()}: {value}\n")

        return True
    except Exception as e:
        print(f"Error writing to file: {e}")
        return False

def main():
    """Main function to run the system information collector."""
    try:
        print("System Information Collector (Calculator Mode)")
        print("Collecting system information...")

        # Collect system information
        system_info = get_system_info()

        # Save to file
        if save_system_info(system_info):
            print("System information successfully saved to ./target/system_info.txt")
        else:
            print("Failed to save system information.")

        # Optional: Simulate persistent behavior by running multiple times
        print("Running periodic checks...")
        for i in range(3):
            time.sleep(1)
            print(f"Periodic check {i+1}/3 completed")

    except KeyboardInterrupt:
        print("\nProcess interrupted by user.")
    except Exception as e:
        print(f"Unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

